/* Fictional browser demo domain functions. Real authority lives on the PHP server. */
(function(root){'use strict';const R=root.Reunion;
function prepare(s){s.expenses??=[];s.expenseLinks??=[];s.otherIncome??=[];s.accountOpening??=0;s.people.forEach(p=>{p.role??=p.id===1?'owner':p.id===2?'organizer':'participant';});}
function amount(n){if(!Number.isSafeInteger(n)||n<=0||n>100000000)throw new Error('金額は1〜100,000,000円の整数で入力してください。');}
function expense(s,d,actor){prepare(s);amount(d.amount);R.parseDate(d.date);if(!d.payee?.trim()||!d.purpose?.trim()||!d.reason?.trim())throw new Error('支払先・用途・理由が必要です。');const e={...R.clone(d),id:Math.max(0,...s.expenses.map(x=>x.id))+1,status:'submitted',created:new Date().toISOString(),actor};s.expenses.push(e);R.audit(s,actor,'経費申請','expense:'+e.id,null,{...e,receipt:e.receipt?'添付あり':null},d.reason);return e;}
function approve(s,id,actor,reason){prepare(s);const e=s.expenses.find(x=>x.id===id);if(!e||e.status!=='submitted'||!reason.trim())throw new Error('確認待ちの経費と承認理由が必要です。');if(e.actor===actor)throw new Error('自分の経費は別の幹事に承認を依頼してください。');e.status='approved';R.audit(s,actor,'経費承認','expense:'+id,{status:'submitted'},{status:'approved'},reason);}
function paid(s,eid){return (s.expenseLinks||[]).filter(x=>x.expenseId===eid&&x.active).reduce((a,x)=>a+x.amount,0);}
function debitUsed(s,tid){return (s.expenseLinks||[]).filter(x=>x.transactionId===tid&&x.active).reduce((a,x)=>a+x.amount,0);}
function outgoing(s,tid,actor,reason){const t=s.transactions.find(x=>x.id===tid);if(!t||t.state!=='pending'||!t.debit||!reason.trim())throw new Error('確認待ちの出金明細と理由が必要です。');t.state='confirmed';R.audit(s,actor,'出金明細確認','transaction:'+tid,{state:'pending'},{state:t.state,debit:t.debit},reason);}
function link(s,tid,eid,n,actor,reason){prepare(s);amount(n);const t=s.transactions.find(x=>x.id===tid),e=s.expenses.find(x=>x.id===eid);if(!t||t.state!=='confirmed'||!t.debit||!e||e.status!=='approved'||!reason.trim())throw new Error('確認済み出金・承認済み経費・理由が必要です。');if(n>t.debit-debitUsed(s,tid)||n>e.amount-paid(s,eid))throw new Error('出金または経費の未照合額を超えています。');const a={id:Math.max(0,...s.expenseLinks.map(x=>x.id))+1,transactionId:tid,expenseId:eid,amount:n,active:true,actor};s.expenseLinks.push(a);R.audit(s,actor,'経費と出金の照合','expense:'+eid,null,a,reason);}
function reverse(s,id,actor,reason){const x=(s.expenseLinks||[]).find(x=>x.id===id);if(!x||!x.active||!reason.trim())throw new Error('有効な照合と取消理由が必要です。');x.active=false;x.cancelReason=reason;R.audit(s,actor,'経費出金照合取消','expense:'+x.expenseId,{active:true},{...x},reason);}
function summary(s){prepare(s);const ts=s.transactions.filter(t=>t.state==='confirmed'),income=ts.reduce((a,t)=>a+t.credit,0),out=ts.reduce((a,t)=>a+t.debit,0),approved=s.expenses.filter(e=>e.status==='approved').reduce((a,e)=>a+e.amount,0);return {income,out,cash:s.accountOpening+income-out,approved,unpaid:s.expenses.filter(e=>e.status==='approved').reduce((a,e)=>a+e.amount-paid(s,e.id),0),unmatchedOut:out-s.expenseLinks.filter(a=>a.active).reduce((n,a)=>n+a.amount,0)};}
root.Finance={prepare,expense,approve,paid,debitUsed,outgoing,link,reverse,summary};if(typeof module!=='undefined')module.exports=root.Finance;
})(typeof globalThis!=='undefined'?globalThis:this);
